/* Bloques: piezas de cuatro celdas que caen y completan filas */
#include "z.h"
#define GW 10
#define GH 20
#define CS 26
static zwin *W; static u32 G[GH][GW]; static int px, py, rot, cur, nxt, score, lines, over, pausa;
static const u16 S[7][4] = {{0x0F00,0x2222,0x00F0,0x4444},{0x6600,0x6600,0x6600,0x6600},{0x0E40,0x4C40,0x4E00,0x4640},{0x06C0,0x4620,0x06C0,0x4620},{0x0C60,0x2640,0x0C60,0x2640},{0x0E80,0xC440,0x2E00,0x4460},{0x0E20,0x44C0,0x8E00,0x6440}};
static const u32 C[7] = {0x22D3EE,0xFACC15,0xA855F7,0x4ADE80,0xF87171,0xFB923C,0x60A5FA};
#define CELL(s, r, x, y) (S[s][r] & (0x8000 >> ((y) * 4 + (x))))
static int fits(int s, int r, int X, int Y) { for (int y = 0; y < 4; y++) for (int x = 0; x < 4; x++) if (CELL(s, r, x, y)) { int a = X + x, b = Y + y; if (a < 0 || a >= GW || b >= GH) return 0; if (b >= 0 && G[b][a]) return 0; } return 1; }
static void spawn(void) { cur = nxt; nxt = rnd() % 7; rot = 0; px = 3; py = -1; if (!fits(cur, rot, px, py)) over = 1; }
static void reset(void) { memset(G, 0, sizeof G); score = lines = over = 0; nxt = rnd() % 7; spawn(); }
static void cell(int X, int Y, u32 c) { g_rect(W, X + 1, Y + 1, CS - 2, CS - 2, c); g_rect(W, X + 1, Y + 1, CS - 2, 3, 0xFFFFFF & (c | 0x404040)); }
static void draw(void) { g_clear(W, 0x1E1B4B); g_rect(W, 0, 0, GW * CS, GH * CS, 0x0F0E2A); for (int y = 0; y < GH; y++) for (int x = 0; x < GW; x++) if (G[y][x]) cell(x * CS, y * CS, G[y][x]); if (!over) { int gy = py; while (fits(cur, rot, px, gy + 1)) gy++; for (int y = 0; y < 4; y++) for (int x = 0; x < 4; x++) if (CELL(cur, rot, x, y)) { g_frame(W, (px + x) * CS + 2, (gy + y) * CS + 2, CS - 4, CS - 4, 0x4C4A7A); if (py + y >= 0) cell((px + x) * CS, (py + y) * CS, C[cur]); } } int X = GW * CS + 14; char b[32]; g_textb(W, X, 14, "Siguiente", 0xFFFFFF); for (int y = 0; y < 4; y++) for (int x = 0; x < 4; x++) if (CELL(nxt, 0, x, y)) cell(X + x * CS, 40 + y * CS, C[nxt]); snprintf(b, 32, _("Puntos %d"), score); g_text(W, X, 160, b, 0xFFFFFF); snprintf(b, 32, _("Filas %d"), lines); g_text(W, X, 182, b, 0xFFFFFF); g_text(W, X, 230, "Flechas", 0xA5B4FC); g_text(W, X, 248, "Espacio cae", 0xA5B4FC); g_text(W, X, 266, "P pausa", 0xA5B4FC); if (over || pausa) g_text2(W, 24, GH * CS / 2 - 16, over ? "Fin: Intro" : "Pausa", 0xFFFFFF, 2); zw_present(W); }
static void lock(void) { for (int y = 0; y < 4; y++) for (int x = 0; x < 4; x++) if (CELL(cur, rot, x, y) && py + y >= 0) G[py + y][px + x] = C[cur]; int n = 0; for (int y = GH - 1; y >= 0; y--) { int full = 1; for (int x = 0; x < GW; x++) if (!G[y][x]) full = 0; if (full) { memmove(G[1], G[0], y * sizeof G[0]); memset(G[0], 0, sizeof G[0]); n++; y++; } } lines += n; static const int pts[] = {0, 40, 100, 300, 1200}; score += pts[n]; spawn(); }
int main(const char *a) { W = zw_new("Bloques", -1, 0, GW * CS + 130, GH * CS, WF_DECOR); reset(); draw(); zevent e; u64 t = z_ms(); for (;;) { int sp = MAX(90, 600 - lines * 12); long l = (long)(t + sp) - (long)z_ms(); if (l < 1) l = 1; if (z_event(&e, l)) { if (e.type == EV_CLOSE) return 0; if (e.type == EV_REDRAW) draw(); if (e.type == EV_KEY) { if (over) { if (e.ch == '\n') reset(); } else if (e.ch == 'p' || e.ch == 'P') pausa = !pausa; else if (!pausa) { if (e.key == K_LEFT && fits(cur, rot, px - 1, py)) px--; else if (e.key == K_RIGHT && fits(cur, rot, px + 1, py)) px++; else if (e.key == K_DOWN) { if (fits(cur, rot, px, py + 1)) { py++; score++; } } else if (e.key == K_UP) { int r = (rot + 1) & 3; for (int k = 0; k < 3; k++) { int o = k == 0 ? 0 : k == 1 ? -1 : 1; if (fits(cur, r, px + o, py)) { rot = r; px += o; break; } } } else if (e.ch == ' ') { while (fits(cur, rot, px, py + 1)) { py++; score += 2; } lock(); } } draw(); } } if (z_ms() >= t + sp) { t = z_ms(); if (!over && !pausa) { if (fits(cur, rot, px, py + 1)) py++; else lock(); } draw(); } } }
